package com.bank.tick.service;

// Simulates an infinite sorted array; out-of-bounds reads return a sentinel.
public class InfiniteReader {
    private final int[] backing;
    public InfiniteReader(int[] backing) { this.backing = backing; }

    public int get(int index) {
        if (index >= backing.length) return Integer.MAX_VALUE; // sentinel = +infinity
        return backing[index];
    }
}
