package com.bank.tick.service;

import java.util.logging.Logger;

// Finds a key in a sorted array of unknown length.
public class TickSearchService {
    private static final Logger log = Logger.getLogger(TickSearchService.class.getName());

    public int search(InfiniteReader reader, int key) {
        int start = 0, end = 1;
        while (reader.get(end) < key) {             // expand window exponentially
            int newEnd = end + (end - start + 1) * 2;
            start = end;
            end = newEnd;
            log.fine(() -> "Expanded window to [" + start + ", " + end + "]");
        }
        while (start <= end) {                       // binary search the bracket
            int mid = start + (end - start) / 2;
            int val = reader.get(mid);               // sentinel pushes search left
            if (val == key) {
                final int found = mid;
                log.info(() -> "Found key " + key + " at index " + found);
                return mid;
            }
            if (key < val) end = mid - 1; else start = mid + 1;
        }
        log.warning(() -> "Key " + key + " not found");
        return -1;
    }
}
